SET work_mem TO '4GB'; SELECT id FROM stackoverflow_posts_fts WHERE body_tsv @@ (SELECT ts_rewrite('python | exception'::tsquery, target, substitute) FROM bench_synonyms_tsquery WHERE 'python | exception'::tsquery @> target) ORDER BY ts_rank(body_tsv, (SELECT ts_rewrite('python | exception'::tsquery, target, substitute) FROM bench_synonyms_tsquery WHERE 'python | exception'::tsquery @> target)) DESC LIMIT 10;
